&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de paladin&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_paladin_0&quot; href=&quot;#Les_arch&#233;types_de_paladin_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-B&#233;ni-(Paladin).html&quot; title=&quot;Bouclier b&#233;ni&quot;&gt;Bouclier b&#233;ni&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Du-Temple-(Paladin).html&quot; title=&quot;Champion du temple&quot;&gt;Champion du temple&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Temp&#233;r&#233;-(Paladin).html&quot; title=&quot;Champion temp&#233;r&#233;&quot;&gt;Champion temp&#233;r&#233;&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Fant&#244;mes-(Paladin).html&quot; title=&quot;Chasseur de fant&#244;mes&quot;&gt;Chasseur de fant&#244;mes&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Divin-(Paladin).html&quot; title=&quot;Chasseur divin&quot;&gt;Chasseur divin&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Des-Pi&#232;ces-(Paladin).html&quot; title=&quot;Chevalier des pi&#232;ces&quot;&gt;Chevalier des pi&#232;ces&lt;/a&gt; (MM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Empyr&#233;en-(Paladin).html&quot; title=&quot;Chevalier empyr&#233;en&quot;&gt;Chevalier empyr&#233;en&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;tincelant-(Paladin).html&quot; title=&quot;Chevalier &#233;tincelant&quot;&gt;Chevalier &#233;tincelant&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Divin-(Paladin).html&quot; title=&quot;D&#233;fenseur divin&quot;&gt;D&#233;fenseur divin&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Elu-(Paladin).html&quot; title=&quot;&#201;lu&quot;&gt;&#201;lu&lt;/a&gt; &lt;i&gt;(FF)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Du-Courage-(Paladin).html&quot; title=&quot;&#201;p&#233;e du courage&quot;&gt;&#201;p&#233;e du courage&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;au-Des-Morts-Vivants-(Paladin).html&quot; title=&quot;Fl&#233;au des morts-vivants&quot;&gt;Fl&#233;au des morts-vivants&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Glaive-De-Lesprit-(Paladin).html&quot; title=&quot;Glaive de l&amp;#39;esprit&quot;&gt;Glaive de l&#39;esprit&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-De-La-Lumi&#232;re-Sainte-(Paladin).html&quot; title=&quot;Guerrier de la lumi&#232;re sainte&quot;&gt;Guerrier de la lumi&#232;re sainte&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Saint-(Paladin).html&quot; title=&quot;Guide saint&quot;&gt;Guide saint&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hospitalier-(Paladin).html&quot; title=&quot;Hospitalier&quot;&gt;Hospitalier&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;L&#233;gat-(Paladin).html&quot; title=&quot;L&#233;gat&quot;&gt;L&#233;gat&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Asserment&#233;-(Paladin).html&quot; title=&quot;Paladin asserment&#233;&quot;&gt;Paladin asserment&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Gris-(Paladin).html&quot; title=&quot;Paladin gris&quot;&gt;Paladin gris&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;dempteur-(Paladin).html&quot; title=&quot;R&#233;dempteur&quot;&gt;R&#233;dempteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Gardien-(Paladin).html&quot; title=&quot;Sage gardien&quot;&gt;Sage gardien&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aasimar-(Race).html&quot; title=&quot;Les aasimars&quot;&gt;Aasimar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Pistolet-(Paladin).html&quot; title=&quot;Saint pistolet&quot;&gt;Saint pistolet&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Tacticien-(Paladin).html&quot; title=&quot;Saint tacticien&quot;&gt;Saint tacticien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-Pierre-(Paladin).html&quot; title=&quot;Seigneur de pierre&quot;&gt;Seigneur de pierre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serviteur-Sacr&#233;-(Paladin).html&quot; title=&quot;Serviteur sacr&#233;&quot;&gt;Serviteur sacr&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;L&#39;antipaladin&lt;/a&gt; (classe alternative) (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Du-S&#233;pulcre-(Paladin).html&quot; title=&quot;Chevalier du s&#233;pulcre&quot;&gt;Chevalier du s&#233;pulcre&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Insinuateur-(Paladin).html&quot; title=&quot;Insinuateur&quot;&gt;Insinuateur&lt;/a&gt; &lt;i&gt;(AoE)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saccageur-(Paladin).html&quot; title=&quot;Saccageur&quot;&gt;Saccageur&lt;/a&gt; &lt;i&gt;(ISC)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Semeur-De-Peur-(Antipaladin).html&quot; title=&quot;Semeur de peur&quot;&gt;Semeur de peur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelours.html&quot; title=&quot;Gobelours&quot;&gt;Gobelours&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-(Antipaladin).html&quot; title=&quot;Tyran&quot;&gt;Tyran&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-De-Fer-(Antipaladin).html&quot; title=&quot;Tyran de fer&quot;&gt;Tyran de fer&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Nain.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Nain.ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Nain.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;nains&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;i&gt;Un seigneur de pierre est une sentinelle d&#233;vou&#233;e qui monte la garde dans les enclaves naines et tire sa puissance de la terre et des vieilles pierres, afin de prot&#233;ger les siens.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Frappe de roche (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Frappe_de_roche_Sur_0&quot; href=&quot;#Frappe_de_roche_Sur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une fois par jour et par niveau de paladin, le seigneur de pierre peut puiser dans la force des pierres vivantes. Gr&#226;ce &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, ses attaques de corps &#224; corps (arm&#233;es ou &#224; mains nues) deviennent magiques et en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Adamantium.html&quot; title=&quot;adamantium&quot;&gt;adamantium&lt;/a&gt; jusqu’au d&#233;but de son prochain tour. Il ignore une &lt;a class=&quot;pagelink&quot; href=&quot;Exploration#Solidite.html&quot; title=&quot;solidit&#233;&quot;&gt;solidit&#233;&lt;/a&gt; jusqu’&#224; deux fois sup&#233;rieure &#224; son niveau de paladin et b&#233;n&#233;ficie d’un bonus de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt;, ainsi qu’aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html&quot; title=&quot;Les manœuvres offensives&quot;&gt;manœuvres offensives&lt;/a&gt;. Ce bonus s’applique aussi &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; si sa personne ou sa cible touche la terre ou une structure de pierre. Ce bonus augmente de +1 au niveau 5 et, ensuite, tous les cinq niveaux. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin#Chatimentdumal.html&quot; title=&quot;Ch&#226;timent du mal&quot;&gt;ch&#226;timent du Mal&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Coeur de roche (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Coeur_de_roche_Ext_1&quot; href=&quot;#Coeur_de_roche_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, la chair du seigneur de pierre devient de plus en plus pierreuse. Il gagne un bonus d’armure naturelle de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt;/adamantium &#233;gale &#224; 1/2 niveau de paladin. Le bonus d’armure naturelle augmente de +1 au niveau 6 et, ensuite, tous les quatre niveaux, avec un maximum de +5 au niveau 18. Ces avantages sont r&#233;duits de moiti&#233; si le paladin ne touche pas la terre ou une structure de pierre. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#GRACEDIVINE&quot; title=&quot;Le paladin&quot;&gt;gr&#226;ce divine&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Sang de roche (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Sang_de_roche_Ext_2&quot; href=&quot;#Sang_de_roche_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, les organes vitaux du seigneur de pierre commencent &#224; se calcifier et son sang se transforme en pierre liquide. Il ajoute son niveau de paladin &#224; ses tests quand il tente de se &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;stabiliser&lt;/a&gt; lorsque ses points de vie sont dans le n&#233;gatif et a 25 % de chances d’ignorer les &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coups critiques&lt;/a&gt; et les d&#233;g&#226;ts de pr&#233;cision. Ce pouvoir ne se cumule pas avec une armure de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;fense-(L&#233;g&#232;re).html&quot; title=&quot;d&#233;fense l&#233;g&#232;re (propri&#233;t&#233;)&quot;&gt;d&#233;fense&lt;/a&gt; ou un effet similaire. Au niveau 9, ces chances passent &#224; 50 % et le seigneur de pierre est immunis&#233; contre la &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#P&#233;trifi&#233;.html&quot; title=&quot;P&#233;trifi&#233;&quot;&gt;p&#233;trification&lt;/a&gt;. Au niveau 15, ces chances passent &#224; 75 % et le seigneur de pierre est immunis&#233; contre les effets de &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Saignement.html&quot; title=&quot;Saignement&quot;&gt;saignement&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Absorption-De-Sang-(Capacit&#233;).html&quot; title=&quot;Absorption de sang (Ext)&quot;&gt;absorption de sang&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#SANTEDIVINE&quot; title=&quot;Le paladin&quot;&gt;sant&#233; divine&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#GRACE&quot; title=&quot;Le paladin&quot;&gt;gr&#226;ces&lt;/a&gt; des niveaux 3, 9 et 15.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Position d&#233;fensive (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Position_d&#233;fensive_Ext_3&quot; href=&quot;#Position_d&#233;fensive_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, le seigneur de pierre gagne le pouvoir de fid&#232;le d&#233;fenseur &lt;a class=&quot;pagelink&quot; href=&quot;Fid&#232;le-D&#233;fenseur.html#POSITIONDEFENSIVE&quot; title=&quot;Le fid&#232;le d&#233;fenseur&quot;&gt;position d&#233;fensive&lt;/a&gt;. Il choisit un &lt;a class=&quot;pagelink&quot; href=&quot;Fid&#232;le-D&#233;fenseur.html#POUVOIRDEFENSIF&quot; title=&quot;Le fid&#232;le d&#233;fenseur&quot;&gt;pouvoir d&#233;fensif&lt;/a&gt; au niveau 8 et, ensuite un autre tous les quatre niveaux. Les niveaux de &lt;a class=&quot;pagelink&quot; href=&quot;Fid&#232;le-D&#233;fenseur.html&quot; title=&quot;Le fid&#232;le d&#233;fenseur&quot;&gt;fid&#232;le d&#233;fenseur&lt;/a&gt; se cumulent avec ceux de paladin quand il s’agit de d&#233;terminer le nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; que dure la position d&#233;fensive chaque jour. Un seigneur de pierre ne gagne pas de sorts ni de pouvoirs magiques, il n’a pas de niveau de lanceur de sorts et ne peut pas utiliser d’&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html#OBJETSAPOTENTIELMAGIQUE&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;objets &#224; potentiel magique&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html#OBJETSAFINDINCANTATION&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;&#224; fin d’incantation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Lien avec la terre (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Lien_avec_la_terre_Sur_4&quot; href=&quot;#Lien_avec_la_terre_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, le seigneur de pierre gagne &lt;a class=&quot;pagelink&quot; href=&quot;Canalisation-&#201;l&#233;mentaire.html&quot; title=&quot;Canalisation &#233;l&#233;mentaire&quot;&gt;Canalisation &#233;l&#233;mentaire&lt;/a&gt; (terre) comme don suppl&#233;mentaire. Il l’active en d&#233;pensant deux utilisations de son &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSITIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;imposition des mains&lt;/a&gt;, en utilisant son niveau de paladin comme niveau de pr&#234;tre. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CANALISATIONDENERGIEPOSITIVE&quot; title=&quot;Le paladin&quot;&gt;canalisation d’&#233;nergie positive&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Serviteur de pierre (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Serviteur_de_pierre_Sur_5&quot; href=&quot;#Serviteur_de_pierre_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, le seigneur de pierre peut appeler un &lt;a class=&quot;pagelink&quot; href=&quot;&#201;l&#233;mentaire-De-La-Terre.html&quot; title=&quot;&#201;l&#233;mentaire de Terre&quot;&gt;&#233;l&#233;mentaire de la terre&lt;/a&gt; de taille P &#224; ses c&#244;t&#233;s, comme un paladin ordinaire appelle sa &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#PACTEDIVIN&quot; title=&quot;Le paladin&quot;&gt;monture&lt;/a&gt;. Cet &#233;l&#233;mentaire est Loyal Bon et d’arch&#233;type &lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types.html#CREATURECELESTE&quot; title=&quot;Les arch&#233;types&quot;&gt;c&#233;leste&lt;/a&gt;. Sa taille augmente au fur et &#224; mesure que le seigneur de pierre gagne des niveaux : il devient de taille M au niveau 8, de taille G au niveau 11, de taille TG au niveau 14, noble au niveau 17 et seigneur au niveau 20. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#PACTEDIVIN&quot; title=&quot;Le paladin&quot;&gt;pacte divin&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Tueur de pierre (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Tueur_de_pierre_Sur_6&quot; href=&quot;#Tueur_de_pierre_Sur_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 11, quand le seigneur de pierre utilise frappe de roche, son attaque gagne la propri&#233;t&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Tueuse.html&quot; title=&quot;tueuse (propri&#233;t&#233;)&quot;&gt;tueuse&lt;/a&gt; contre les cr&#233;atures de &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Terre.html&quot; title=&quot;Terre (sous-type)&quot;&gt;sous-type terre&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Cr&#233;ature-Artificielle.html&quot; title=&quot;Cr&#233;ature artificielle&quot;&gt;cr&#233;atures artificielles&lt;/a&gt; ou les objets faits de terre ou de pierre. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin#Auradejustice.html&quot; title=&quot;Aura de justice&quot;&gt;aura de justice&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Frappe de phase (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Frappe_de_phase_Sur_7&quot; href=&quot;#Frappe_de_phase_Sur_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 12, la frappe de roche du seigneur de pierre peut traverser la pierre et le m&#233;tal comme s’ils n’existaient pas. S’il d&#233;pense deux utilisations de son pouvoir de frappe de roche, il peut ignorer un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat#Abri.html&quot; title=&quot;abri&quot;&gt;abri&lt;/a&gt; (s’il n’est pas total) offert par de la roche ou du m&#233;tal. Il ignore aussi les bonus que les armures de pierre ou de m&#233;tal apportent &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, comme s’il maniait une arme de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Lumi&#232;re.html&quot; title=&quot;lumi&#232;re (propri&#233;t&#233;)&quot;&gt;lumi&#232;re&lt;/a&gt;. La frappe de phase n’endommage pas les cr&#233;atures artificielles, les objets ni les cr&#233;atures de sous-type terre, mais, contrairement aux armes de lumi&#232;re, elle blesse les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;morts-vivants&lt;/a&gt;. Ce pouvoir remplace la &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#GRACE&quot; title=&quot;Le paladin&quot;&gt;gr&#226;ce&lt;/a&gt; de niveau 12.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;fense mobile (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;fense_mobile_Ext_8&quot; href=&quot;#D&#233;fense_mobile_Ext_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 18, un seigneur de pierre peut faire un pas de 1,50 m&#232;tre par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; tout en maintenant sa position d&#233;fensive. Ce pouvoir remplace la gr&#226;ce de niveau 18.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Corps de pierre (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Corps_de_pierre_Ext_9&quot; href=&quot;#Corps_de_pierre_Ext_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 20, le corps du seigneur de pierre se transforme en pierre vivante. Le seigneur n’a plus besoin de manger, de boire, de respirer ni de dormir. Il est immunis&#233; contre la paralysie, le &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;poison&quot;&gt;poison&lt;/a&gt; et l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;tourdi.html&quot; title=&quot;&#201;tourdi&quot;&gt;&#233;tourdissement&lt;/a&gt;. Il n’est plus sensible aux &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coups critiques&lt;/a&gt; et aux d&#233;g&#226;ts de pr&#233;cision. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin#Championsacre.html&quot; title=&quot;Champion sacr&#233;&quot;&gt;champion sacr&#233;&lt;/a&gt;.
